import{_ as i}from"./chunks/verwaltung-einstellungen-vermerke.BM7Maf45.js";import{_ as a,o as l,c as s,a3 as n,j as e,a as t}from"./chunks/framework.z_KJ15Ep.js";const o="/bilder/schueler/vermerke.png",d="/bilder/schueler/akt-halbj-laufbahninfo-2.png",_=JSON.parse('{"title":"Vermerke zu Schülerdatensätzen führen","description":"","frontmatter":{"title":"Vermerke zu Schülerdatensätzen führen","source_pageid":1345,"source_revision":6072},"headers":[],"relativePath":"schild3/schueler/vermerke-schueler.md","filePath":"schild3/schueler/vermerke-schueler.md"}'),m={name:"schild3/schueler/vermerke-schueler.md"};function u(c,r,h,k,p,g){return l(),s("div",null,[...r[0]||(r[0]=[n('<h1 id="vermerke-zu-schulerdatensatzen-fuhren" tabindex="-1">Vermerke zu Schülerdatensätzen führen <a class="header-anchor" href="#vermerke-zu-schulerdatensatzen-fuhren" aria-label="Permalink to &quot;Vermerke zu Schülerdatensätzen führen&quot;">​</a></h1><p>Erfassen Sie Vermerkart, Datum und Bemerkung zu einem Schülerdatensatz. Bereiten Sie Vermerkarten im Katalog vor und beachten Sie die vorhandenen Datenschutzhinweise.</p><p><a href="/bilder/schueler/vermerke.png"><img src="'+o+'" alt="Anlegen, Löschen, Bearbeiten und Entfernen von Vermerken." loading="lazy"></a></p><p><em>Anlegen, Löschen, Bearbeiten und Entfernen von Vermerken.</em></p><p>Wählen Sie im Schülercontainer die gewünschte Person aus. Unter <strong>Schüler ➜ Vermerke</strong> können Sie zu dieser Person Vermerke anlegen.</p><p>Jeder Vermerk besteht aus einer <em>Vermerkart</em>, einem <em>Datum</em> der Anlage, einer optionalen <em>Bemerkung</em> und wer den Vermerk <em>angelegt</em> und dann wer ihn zuletzt <em>geändert</em> hat.</p><p><strong>Lange Bemerkungen anzeigen</strong></p><p>Lange Bemerkungen werden komplett angezeigt, wenn die Zeilenhöhe vergrößert wird. Dazu den Mauscursor in der ganz linken Spalte zwischen die Zeilen bewegen bis sich der Cursor in einen vertikalen Doppelpfeil ändert. Nun kann die Zeile größer gezogen werden.</p><p>Die Vermerkarten können über <em>Kataloge</em> ➜ <em>Vermerkarten</em> wie bei Katalogen üblich verwaltet werden.</p>',9),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),t("Wichtig")]),e("p",null,"Bei der Anlage der Vermerkarten wie auch bei der der Eingabe eines frei formulierten Textes in das Schreibfeld unterhalb der ausgewählten Vermerkart ist der Datenschutz zu beachten!")],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),t("Tipp")]),e("p",null,"Tragen Sie möglichst immer ein Datum ein. So können Sie alte Einträge leichter erkennen und bei der Suche einen Datumsbereich verwenden.")],-1),n('<p><a href="/bilder/schueler/akt-halbj-laufbahninfo-2.png"><img src="'+d+'" alt="Filtern auf gesetzte Vermerke." loading="lazy"></a></p><p><em>Filtern auf gesetzte Vermerke.</em></p><p>Mit <em>Auswahl</em> ➜ <em>Schülerfilter</em> können auf der Karte Weitere Daten im Bereich Vermerke nach <em>&quot;Art&quot;</em> und <em>&quot;Teil des Vermerk-Textes&quot;</em> Eingaben gesucht werden, bei <em>&quot;Vermerkdatum von...bis&quot;</em> kann ein Zeitbereich gewählt werden.</p><p>Ein <code>Doppelklick</code> auf das Feld <em>Bemerkung</em> öffnet den Editor für Floskeln, so dass zuvor festgelegte Floskeln für Vermerke direkt verwendet werden können.</p><p><a href="/bilder/schueler/verwaltung-einstellungen-vermerke.png"><img src="'+i+'" alt="Ein- und Ausblenden des Reiter Schüler ➜ Vermerke." loading="lazy"></a></p><p><em>Ein- und Ausblenden des Reiter Schüler ➜ Vermerke.</em></p><p>Falls Sie an Ihrer Schule Vermerke nicht verwenden möchten, kann der Reiter über <em>Verwaltung ➜ Einstellungen ➜ Globale Einstellungen ➜ Allgemeines ➜ Ansicht</em> über den Haken bei <strong>Karteireiter &quot;Vermerke&quot; zeigen</strong> ausgeblendet werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Vermerke_(Sch%C3%BCler)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6072.</p>',9)])])}const v=a(m,[["render",u]]);export{_ as __pageData,v as default};
